import React, { useState, useEffect, useRef } from 'react';
import { 
  Box, 
  Text, 
  Button, 
  Flex, 
  Icon,
  useColorModeValue 
} from '@chakra-ui/react';
import { RefreshCw, Square } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import ReactMarkdown from 'react-markdown';

/**
 * Response section that appears below internal thoughts
 * Supports markdown rendering with fade-in animation
 */
const ResponseSection = ({ 
  message, 
  isStreaming = false, 
  onRetry = null, 
  onStop = null 
}) => {
  const [displayContent, setDisplayContent] = useState('');
  const [showCursor, setShowCursor] = useState(false);
  const contentRef = useRef(null);
  const cursorIntervalRef = useRef(null);

  // Theme colors - moved to top to avoid hooks rules violations
  const accentColor = '#4415b6';
  const textColor = useColorModeValue('gray.800', 'gray.100');
  const mutedText = useColorModeValue('gray.600', 'gray.400');
  const codeBg = useColorModeValue('gray.100', 'gray.700');
  const errorBg = useColorModeValue('red.50', 'red.900');
  const errorText = useColorModeValue('red.800', 'red.200');
  const errorBorder = useColorModeValue('red.200', 'red.700');
  const blockquoteBg = useColorModeValue('gray.50', 'gray.800');
  const tableBorderColor = useColorModeValue('gray.200', 'gray.600');
  const tableHeaderBg = useColorModeValue('gray.100', 'gray.700');

  // Update display content
  useEffect(() => {
    if (message.content) {
      setDisplayContent(message.content);
    }
  }, [message.content]);

  // Manage cursor blinking during streaming
  useEffect(() => {
    if (isStreaming && message.content) {
      setShowCursor(true);
      cursorIntervalRef.current = setInterval(() => {
        setShowCursor(prev => !prev);
      }, 500);
    } else {
      setShowCursor(false);
      if (cursorIntervalRef.current) {
        clearInterval(cursorIntervalRef.current);
        cursorIntervalRef.current = null;
      }
    }

    return () => {
      if (cursorIntervalRef.current) {
        clearInterval(cursorIntervalRef.current);
      }
    };
  }, [isStreaming, message.content]);

  // Auto-scroll during streaming
  useEffect(() => {
    if (contentRef.current && isStreaming) {
      contentRef.current.scrollTop = contentRef.current.scrollHeight;
    }
  }, [displayContent, isStreaming]);

  // Clean message content
  const cleanMessageContent = () => {
    if (!displayContent) return '';
    
    let cleanedContent = displayContent;
    
    // Remove any internal thoughts tags that might have leaked through
    cleanedContent = cleanedContent.replace(/<internal_thoughts>[\s\S]*?<\/internal_thoughts>/g, '');
    cleanedContent = cleanedContent.replace(/<internal[^>]*thoughts[^>]*>/g, '');
    cleanedContent = cleanedContent.replace(/<\/internal[^>]*thoughts[^>]*>/g, '');
    cleanedContent = cleanedContent.replace(/internal_thoughts/g, '');
    
    // Clean up excessive whitespace
    cleanedContent = cleanedContent.replace(/\s+/g, ' ').trim();
    
    return cleanedContent;
  };

  // Check if we should show the response section
  const hasContent = displayContent && displayContent.trim().length > 0;
  const hasError = message.metadata?.error;
  
  // Check if internal thoughts are still processing
  const hasProcessingSteps = message.metadata?.processingSteps?.length > 0;
  const isProcessingThoughts = hasProcessingSteps && 
    message.metadata.processingSteps.some(step => step.status === 'in_progress');
  
  // Only show response if:
  // 1. We have content AND internal thoughts are done processing, OR
  // 2. We have an error, OR  
  // 3. We're streaming but only if we're past the thinking phase (have content)
  const shouldShow = (hasContent && !isProcessingThoughts) || hasError || 
    (isStreaming && hasContent && !isProcessingThoughts);

  if (!shouldShow) return null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, ease: 'easeOut' }}
    >
      <Box mb={3}>
        {/* Error state */}
        {hasError && (
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.3 }}
          >
            <Box
              bg={errorBg}
              borderWidth="1px"
              borderColor={errorBorder}
              borderRadius="md"
              p={3}
              mb={3}
            >
              <Flex align="center" justify="space-between">
                <Box flex="1">
                  <Text fontSize="sm" fontWeight="medium" color={errorText} mb={1}>
                    Error occurred
                  </Text>
                  <Text fontSize="xs" color={errorText}>
                    {message.metadata.error.message}
                  </Text>
                  {message.metadata.error.error_code && (
                    <Text fontSize="xs" color={mutedText} mt={1} fontFamily="mono">
                      Code: {message.metadata.error.error_code}
                    </Text>
                  )}
                </Box>
                {onRetry && (
                  <Button
                    size="sm"
                    colorScheme="red"
                    variant="ghost"
                    leftIcon={<Icon as={RefreshCw} boxSize={3} />}
                    onClick={onRetry}
                    ml={3}
                  >
                    Retry
                  </Button>
                )}
              </Flex>
            </Box>
          </motion.div>
        )}

        {/* Response content */}
        {hasContent && (
          <Box
            ref={contentRef}
            color={textColor}
            fontSize="sm"
            lineHeight="1.6"
            sx={{
              '& p': { mb: 2 },
              '& p:last-child': { mb: 0 },
              '& ul, & ol': { pl: 4, mb: 2 },
              '& li': { mb: 1 },
              '& h1, & h2, & h3': { 
                fontWeight: 'semibold', 
                mb: 2, 
                mt: 3,
                color: accentColor
              },
              '& h1:first-child, & h2:first-child, & h3:first-child': { mt: 0 },
              '& code': { 
                bg: codeBg, 
                px: 1, 
                py: 0.5, 
                borderRadius: 'sm',
                fontSize: 'xs',
                fontFamily: 'mono'
              },
              '& pre': { 
                bg: codeBg, 
                p: 3, 
                borderRadius: 'md',
                overflow: 'auto',
                fontSize: 'xs'
              },
              '& blockquote': {
                borderLeft: '4px solid',
                borderLeftColor: accentColor,
                pl: 3,
                py: 1,
                bg: blockquoteBg,
                fontStyle: 'italic'
              },
              '& table': {
                width: 'full',
                borderCollapse: 'collapse',
                mb: 2
              },
              '& th, & td': {
                border: '1px solid',
                borderColor: tableBorderColor,
                px: 2,
                py: 1,
                fontSize: 'xs'
              },
              '& th': {
                bg: tableHeaderBg,
                fontWeight: 'semibold'
              }
            }}
          >
            <ReactMarkdown>{cleanMessageContent()}</ReactMarkdown>
            
            {/* Streaming cursor */}
            {isStreaming && showCursor && (
              <motion.span
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="inline-block w-0.5 h-4 bg-blue-500 ml-1"
                style={{
                  animation: 'blink 1s infinite'
                }}
              />
            )}
          </Box>
        )}

        {/* Streaming controls */}
        {isStreaming && onStop && (
          <motion.div
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
          >
            <Flex justify="flex-end" mt={2}>
              <Button
                size="sm"
                colorScheme="red"
                variant="ghost"
                leftIcon={<Icon as={Square} boxSize={3} />}
                onClick={onStop}
              >
                Stop
              </Button>
            </Flex>
          </motion.div>
        )}

        {/* Add CSS for cursor blink animation */}
        <style jsx>{`
          @keyframes blink {
            0%, 50% { opacity: 1; }
            51%, 100% { opacity: 0; }
          }
        `}</style>
      </Box>
    </motion.div>
  );
};

export default ResponseSection; 