import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Progress, 
  Text, 
  Flex, 
  useColorModeValue,
  keyframes
} from '@chakra-ui/react';
import { motion } from 'framer-motion';

// Define keyframes for gradient animation
const gradientShift = keyframes`
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
`;

/**
 * Progress indicator with continuous pulse animation
 * Shows processing steps and overall progress
 */
const ProgressIndicator = ({ 
  message, 
  isStreaming = false 
}) => {
  const [progress, setProgress] = useState(0);
  const [currentStep, setCurrentStep] = useState(0);

  // Theme colors
  const accentColor = '#4415b6';
  const progressBg = useColorModeValue('gray.200', 'gray.600');
  const textColor = useColorModeValue('gray.700', 'gray.300');

  // Calculate progress based on processing steps
  useEffect(() => {
    console.log('🔄 ProgressIndicator useEffect triggered:', {
      hasSteps: message.metadata?.processingSteps?.length > 0,
      stepsLength: message.metadata?.processingSteps?.length,
      isStreaming,
      steps: message.metadata?.processingSteps
    });

    if (message.metadata?.processingSteps && Array.isArray(message.metadata.processingSteps)) {
      const steps = message.metadata.processingSteps;
      
      // Get the total steps from the first step that has totalSteps, or use array length
      const totalSteps = steps.length > 0 && steps[0].totalSteps ? steps[0].totalSteps : steps.length;
      
      if (totalSteps > 0 && steps.length > 0) {
        // Count completed and in-progress steps
        const completedSteps = steps.filter(step => step.status === 'completed').length;
        const inProgressSteps = steps.filter(step => step.status === 'in_progress').length;
        
        // Calculate progress: completed steps + 0.5 for in-progress steps
        const effectiveProgress = completedSteps + (inProgressSteps * 0.5);
        const calculatedProgress = Math.min((effectiveProgress / totalSteps) * 100, 100);
        
        // Current step calculation
        let currentStepNumber;
        if (completedSteps === totalSteps) {
          // All steps completed
          currentStepNumber = totalSteps;
        } else if (inProgressSteps > 0) {
          // Some steps in progress
          currentStepNumber = completedSteps + 1;
        } else {
          // Starting or no progress yet
          currentStepNumber = Math.max(completedSteps, 1);
        }
        
        console.log('📊 Progress calculation:', { 
          totalSteps, 
          completedSteps,
          inProgressSteps,
          effectiveProgress, 
          calculatedProgress,
          currentStepDisplay: currentStepNumber,
          steps: steps.map((s, index) => ({ 
            index: index + 1,
            stepNum: s.stepNumber, 
            status: s.status, 
            message: s.message || s.state || s.step 
          }))
        });
        
        setProgress(calculatedProgress);
        setCurrentStep(currentStepNumber);
      } else {
        // No steps yet, show initial state
        console.log('📊 No steps available, setting initial state');
        setProgress(0);
        setCurrentStep(0);
      }
    } else if (isStreaming) {
      // Indeterminate progress animation when no steps available
      console.log('📊 Using indeterminate progress for streaming without steps');
      const interval = setInterval(() => {
        setProgress(prev => {
          const newProgress = prev + 3;
          return newProgress > 100 ? 0 : newProgress;
        });
      }, 150);
      
      return () => clearInterval(interval);
    } else {
      // Reset when not streaming and no steps
      console.log('📊 Resetting progress - not streaming and no steps');
      setProgress(0);
      setCurrentStep(0);
    }
  }, [message.metadata?.processingSteps, isStreaming, message.isGenerating]);

  if (!isStreaming && (!message.metadata?.processingSteps || message.metadata.processingSteps.length === 0)) {
    return null;
  }

  const hasSteps = message.metadata?.processingSteps?.length > 0;
  const totalSteps = message.metadata?.processingSteps?.length || 0;

  return (
    <Box mb={3}>
      {/* Progress bar with pulse animation */}
      <motion.div
        initial={{ opacity: 0, scaleX: 0 }}
        animate={{ opacity: 1, scaleX: 1 }}
        transition={{ duration: 0.5 }}
        key={`progress-${progress}-${currentStep}`}
      >
        <Progress
          value={hasSteps ? progress : undefined}
          isIndeterminate={!hasSteps && isStreaming}
          size="sm"
          colorScheme="purple"
          bg={progressBg}
          borderRadius="full"
          sx={{
            '& > div': {
              background: hasSteps 
                ? `linear-gradient(90deg, ${accentColor}, #6b46c1, ${accentColor})`
                : `linear-gradient(90deg, ${accentColor}, #6b46c1, ${accentColor})`,
              backgroundSize: '200% 100%',
              animation: isStreaming ? `${gradientShift} 2s ease-in-out infinite` : 'none',
            },
          }}
        />
        
        {/* Debug info */}
        {process.env.NODE_ENV === 'development' && (
          <Text fontSize="xs" color="red.500" mt={1}>
            Debug: Progress={progress}%, Step={currentStep}, HasSteps={hasSteps}, Streaming={isStreaming}
          </Text>
        )}
      </motion.div>

      {/* Step counter - show if we have actual steps */}
      {hasSteps && totalSteps > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 5 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <Flex justify="space-between" align="center" mt={1}>
            <Text fontSize="xs" color={textColor}>
              Step {Math.max(currentStep, 1)} of {totalSteps}
            </Text>
            <Text fontSize="xs" color={textColor} fontWeight="medium">
              {Math.round(progress)}%
            </Text>
          </Flex>
        </motion.div>
      )}

      {/* Current processing step */}
      {hasSteps && message.metadata.processingSteps && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          {message.metadata.processingSteps
            .filter(step => step.status === 'in_progress')
            .map((step, index) => (
              <Text
                key={index}
                fontSize="xs"
                color={accentColor}
                mt={1}
                fontWeight="medium"
                opacity={0.8}
                sx={{
                  animation: 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite'
                }}
              >
                {step.message || step.state || step.step || 'Processing...'}
              </Text>
            ))}
        </motion.div>
      )}

      {/* Show general processing message when no specific steps */}
      {!hasSteps && isStreaming && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          <Text
            fontSize="xs"
            color={textColor}
            mt={1}
            textAlign="center"
            fontStyle="italic"
            sx={{
              animation: 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite'
            }}
          >
            Processing your request...
          </Text>
        </motion.div>
      )}
    </Box>
  );
};

export default ProgressIndicator; 