import React from 'react';
import { Box } from '@chakra-ui/react';
import MessageList from './MessageList';

/**
 * Main chat container component
 * Handles the overall layout and structure of the chat interface
 */
const ChatContainer = ({ 
  messages = [], 
  isLoading = false,
  onRetry = null,
  onStop = null,
  className = ''
}) => {
  return (
    <Box 
      className={`chat-container ${className}`}
      h="full"
      display="flex"
      flexDirection="column"
      overflow="hidden"
    >
      <MessageList
        messages={messages}
        isLoading={isLoading}
        onRetry={onRetry}
        onStop={onStop}
      />
    </Box>
  );
};

export default ChatContainer; 