import React from 'react';
import { Box, Flex, Icon, useColorModeValue } from '@chakra-ui/react';
import { Bot } from 'lucide-react';
import { motion } from 'framer-motion';
import InternalThoughtsSection from './InternalThoughtsSection';
import ResponseSection from './ResponseSection';
import SourcesSection from './SourcesSection';

/**
 * LLM message component with clean, minimal appearance
 * Features: no background, no border, left-aligned
 * Contains: internal thoughts, response, and sources sections
 */
const LLMMessage = ({ 
  message, 
  isStreaming = false, 
  onRetry = null, 
  onStop = null 
}) => {
  // Theme colors
  const accentColor = '#4415b6';
  const iconBg = useColorModeValue('gray.100', 'gray.700');
  const textColor = useColorModeValue('gray.800', 'gray.100');

  return (
    <Box display="flex" justifyContent="flex-start" w="full">
      <motion.div
        initial={{ opacity: 0, x: -20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.3 }}
        style={{ width: '100%', maxWidth: '85%' }}
      >
        <Flex gap={3} align="flex-start">
          {/* Avatar */}
          <Flex
            h="32px"
            w="32px"
            alignItems="center"
            justifyContent="center"
            rounded="full"
            bg={iconBg}
            color={accentColor}
            flexShrink={0}
            mt={1}
          >
            <Icon as={Bot} boxSize={4} />
          </Flex>

          {/* Message Content */}
          <Box flex="1" minW={0}>
            {/* Internal Thoughts Section */}
            <InternalThoughtsSection
              message={message}
              isStreaming={isStreaming}
              onStop={onStop}
            />

            {/* Response Section */}
            <ResponseSection
              message={message}
              isStreaming={isStreaming}
              onRetry={onRetry}
              onStop={onStop}
            />

            {/* Sources Section */}
            <SourcesSection
              message={message}
              isStreaming={isStreaming}
            />
          </Box>
        </Flex>
      </motion.div>
    </Box>
  );
};

export default LLMMessage; 