import React from 'react';
import { Box, Text, useColorModeValue } from '@chakra-ui/react';
import { motion } from 'framer-motion';

/**
 * User message component with styled appearance
 * Features: bordered, colored background, right-aligned
 */
const UserMessage = ({ message }) => {
  // Theme colors - moved to top to avoid hooks rules violations
  const userBg = useColorModeValue('blue.50', 'blue.900');
  const userBorder = useColorModeValue('blue.200', 'blue.700');
  const userText = useColorModeValue('blue.900', 'blue.100');
  const timestampColor = useColorModeValue('blue.600', 'blue.400');
  const accentColor = '#4415b6';

  return (
    <Box display="flex" justifyContent="flex-end" w="full">
      <motion.div
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.3 }}
        style={{ maxWidth: '70%' }}
      >
        <Box
          bg={userBg}
          borderWidth="1px"
          borderColor={userBorder}
          borderRadius="lg"
          p={4}
          boxShadow="sm"
          position="relative"
          _before={{
            content: '""',
            position: 'absolute',
            top: '50%',
            right: '-8px',
            transform: 'translateY(-50%)',
            width: 0,
            height: 0,
            borderLeft: '8px solid',
            borderLeftColor: userBorder,
            borderTop: '8px solid transparent',
            borderBottom: '8px solid transparent',
          }}
          _after={{
            content: '""',
            position: 'absolute',
            top: '50%',
            right: '-7px',
            transform: 'translateY(-50%)',
            width: 0,
            height: 0,
            borderLeft: '7px solid',
            borderLeftColor: userBg,
            borderTop: '7px solid transparent',
            borderBottom: '7px solid transparent',
          }}
        >
          <Text
            color={userText}
            fontSize="sm"
            lineHeight="1.6"
            whiteSpace="pre-wrap"
            wordBreak="break-word"
          >
            {message.content}
          </Text>
          
          {/* Timestamp */}
          {message.timestamp && (
            <Text
              fontSize="xs"
              color={timestampColor}
              mt={2}
              textAlign="right"
              opacity={0.7}
            >
              {new Date(message.timestamp).toLocaleTimeString([], { 
                hour: '2-digit', 
                minute: '2-digit' 
              })}
            </Text>
          )}
        </Box>
      </motion.div>
    </Box>
  );
};

export default UserMessage; 