import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Text, 
  Collapse, 
  Flex, 
  Icon,
  useColorModeValue,
  Badge,
  IconButton,
  VStack,
  Spinner
} from '@chakra-ui/react';
import { ChevronDown, ChevronUp, Brain, Square, CheckCircle } from 'lucide-react';
import { motion } from 'framer-motion';
import ProgressIndicator from './ProgressIndicator';

/**
 * Internal thoughts section with collapsible behavior
 * Shows progress during processing, collapses after completion
 */
const InternalThoughtsSection = ({ 
  message, 
  isStreaming = false, 
  onStop = null 
}) => {
  const [isExpanded, setIsExpanded] = useState(true);

  // Theme colors
  const accentColor = '#4415b6';
  const mutedText = useColorModeValue('gray.600', 'gray.400');
  const headerBg = useColorModeValue('purple.50', 'purple.800');
  const hoverBg = useColorModeValue('purple.100', 'purple.700');
  const textColor = useColorModeValue('gray.800', 'gray.100');
  const stepBg = useColorModeValue('white', 'gray.800');
  const contentBg = useColorModeValue('gray.50', 'gray.800');
  const borderColor = useColorModeValue('gray.200', 'gray.600');

  // Check if we have internal thoughts or processing state
  const hasInternalThoughts = message.metadata?.internal_thoughts;
  const hasProcessingSteps = message.metadata?.processingSteps?.length > 0;
  const processingState = message.processingState;
  const shouldShow = hasInternalThoughts || hasProcessingSteps || (isStreaming && processingState);

  // Auto-collapse after completion with animation
  useEffect(() => {
    if (isStreaming) {
      setIsExpanded(true);
    } else if (hasInternalThoughts || hasProcessingSteps) {
      // Auto-collapse after 2 seconds when streaming completes
      const timer = setTimeout(() => {
        setIsExpanded(false);
      }, 2000);
      
      return () => clearTimeout(timer);
    }
  }, [isStreaming, hasInternalThoughts, hasProcessingSteps]);

  if (!shouldShow) return null;

  const toggleExpanded = () => {
    setIsExpanded(!isExpanded);
  };

  return (
    <Box mb={4}>
      {/* Header with brain icon and toggle */}
      <Flex 
        align="center" 
        justify="space-between" 
        cursor="pointer" 
        onClick={toggleExpanded}
        p={3}
        bg={headerBg}
        borderRadius="md"
        borderWidth="1px"
        borderColor={borderColor}
        _hover={{ 
          bg: hoverBg,
          borderColor: accentColor,
          transform: 'translateY(-1px)'
        }}
        transition="all 0.2s"
      >
        <Flex align="center" gap={2}>
          <Icon 
            as={Brain} 
            color={accentColor} 
            boxSize={4}
            sx={{
              animation: isStreaming ? 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite' : 'none'
            }}
          />
          <Text 
            fontWeight="medium" 
            color={textColor}
            fontSize="sm"
          >
            Internal Thoughts
          </Text>
          {isStreaming && (
            <Badge 
              colorScheme="purple" 
              variant="subtle" 
              fontSize="xs"
              ml={1}
            >
              Processing
            </Badge>
          )}
        </Flex>
        
        <Flex align="center" gap={2}>
          {/* Stop button during streaming */}
          {isStreaming && onStop && (
            <IconButton
              size="xs"
              variant="ghost"
              colorScheme="red"
              icon={<Icon as={Square} boxSize={3} />}
              onClick={(e) => {
                e.stopPropagation();
                onStop();
              }}
              aria-label="Stop processing"
              _hover={{ bg: 'red.100' }}
            />
          )}
          
          <Icon 
            as={isExpanded ? ChevronUp : ChevronDown} 
            color={mutedText}
            boxSize={4}
            transition="transform 0.2s"
          />
        </Flex>
      </Flex>

      {/* Collapsible content */}
      <Collapse in={isExpanded} animateOpacity>
        <Box 
          mt={2}
          p={4}
          bg={contentBg}
          borderRadius="md"
          borderWidth="1px"
          borderColor={borderColor}
          borderTopRadius={0}
        >
          {/* Progress indicator */}
          {(isStreaming || message.metadata?.processingSteps?.length > 0) && (
            <ProgressIndicator 
              message={message} 
              isStreaming={isStreaming} 
            />
          )}

          {/* Processing steps */}
          {message.metadata?.processingSteps && message.metadata.processingSteps.length > 0 && (
            <VStack align="stretch" spacing={2} mb={3}>
              <Text fontSize="xs" fontWeight="medium" color={mutedText} mb={1}>
                Processing Steps:
              </Text>
              {message.metadata.processingSteps.map((step, index) => (
                <motion.div
                  key={index}
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.1 }}
                >
                  <Flex align="flex-start" gap={2} p={2} bg={stepBg} borderRadius="sm">
                    <Box
                      w={2}
                      h={2}
                      borderRadius="full"
                      bg={
                        step.status === 'completed' ? 'green.400' :
                        step.status === 'in_progress' ? accentColor :
                        'gray.300'
                      }
                      mt={1}
                      flexShrink={0}
                      sx={{
                        animation: step.status === 'in_progress' ? 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite' : 'none'
                      }}
                    />
                    <Box flex="1" minW={0}>
                      <Text fontSize="xs" color={textColor} fontWeight="medium">
                        {step.message || step.state || step.step || `Step ${step.stepNumber || index + 1}`}
                      </Text>
                      {step.details && (
                        <Text fontSize="xs" color={mutedText} mt={0.5} fontStyle="italic">
                          {step.details}
                        </Text>
                      )}
                    </Box>
                    {step.status === 'completed' && (
                      <Icon as={CheckCircle} color="green.400" boxSize={3} mt={0.5} />
                    )}
                  </Flex>
                </motion.div>
              ))}
            </VStack>
          )}

          {/* Internal thoughts content */}
          {message.metadata?.internal_thoughts && (
            <Box>
              <Text fontSize="xs" fontWeight="medium" color={mutedText} mb={2}>
                Reasoning:
              </Text>
              <Box 
                p={3}
                bg={stepBg}
                borderRadius="sm"
                borderLeft="3px solid"
                borderLeftColor={accentColor}
                borderWidth="1px"
                borderColor={borderColor}
              >
                <Text 
                  fontSize="sm" 
                  color={textColor}
                  lineHeight="1.5"
                  whiteSpace="pre-wrap"
                >
                  {message.metadata.internal_thoughts}
                </Text>
              </Box>
            </Box>
          )}

          {/* Show placeholder when no content yet */}
          {!message.metadata?.internal_thoughts && 
           (!message.metadata?.processingSteps || message.metadata.processingSteps.length === 0) && 
           isStreaming && (
            <Box textAlign="center" py={4}>
              <Spinner size="sm" color={accentColor} mb={2} />
              <Text fontSize="xs" color={mutedText} fontStyle="italic">
                Analyzing your request...
              </Text>
            </Box>
          )}

          {/* Show completion message when done */}
          {!isStreaming && message.metadata?.processingSteps && (
            <Box textAlign="center" mt={2}>
              <Text fontSize="xs" color="green.500" fontWeight="medium">
                ✓ Processing completed
              </Text>
            </Box>
          )}
        </Box>
      </Collapse>
    </Box>
  );
};

export default InternalThoughtsSection; 